  - {subpath: "project-control", kind: "test", command: "python3 -c 'import hashlib, json, pathlib, re, struct, zlib; p = pathlib.Path(\"docs/evidence/SLICE-05\"); rec = json.loads((p / \"hil_deployment_receipt.json\").read_text(encoding=\"utf-8\")); raw_bytes = (p / \"hil_raw_hex.log\").read_bytes(); raw = raw_bytes.decode(\"utf-8\"); prov = rec[\"hw_provenance\"]; st = rec[\"stages\"]; assert rec[\"passed\"] is True and rec[\"probe_rs_used\"] is False and rec[\"heating_pwm_pct\"] == 0 and prov[\"irq_after\"] - prov[\"irq_before\"] > 100 and hashlib.sha256(raw_bytes).hexdigest() == rec[\"raw_hex_log\"][\"sha256\"]; tx_th = [bytes.fromhex(m.group(1)) for m in re.finditer(r\"\\[B2_TH\\][^\\n]*\\bTX\\s+([0-9a-fA-F]+)\", raw)]; tx_mc = [bytes.fromhex(m.group(1)) for m in re.finditer(r\"\\[B2_MC\\][^\\n]*\\bTX\\s+([0-9a-fA-F]+)\", raw)]; d_th = {struct.unpack(\"<I\", b[12:16])[0]: b[20:20 + struct.unpack(\"<H\", b[16:18])[0]] for b in tx_th if len(b) >= 22 and b[0] == 0x55 and b[1] == 0xAA and b[5] == 0x21}; d_mc = {struct.unpack(\"<I\", b[12:16])[0]: b[20:20 + struct.unpack(\"<H\", b[16:18])[0]] for b in tx_mc if len(b) >= 22 and b[0] == 0x55 and b[1] == 0xAA and b[5] == 0x21}; th_pay = b\"\".join(d_th[k] for k in sorted(d_th)); mc_pay = b\"\".join(d_mc[k] for k in sorted(d_mc)); assert len(d_th) == 151 and (zlib.crc32(th_pay) & 0xFFFFFFFF) == 0x6E82DD49 and hashlib.sha256(th_pay).hexdigest() == rec[\"packages\"][\"th\"][\"payload_sha256\"]; assert len(d_mc) == 751 and (zlib.crc32(mc_pay) & 0xFFFFFFFF) == 0x8DC0DC33 and hashlib.sha256(mc_pay).hexdigest() == rec[\"packages\"][\"mc\"][\"payload_sha256\"]; assert st[\"B4_TH\"][\"abort_0x24_active_lease\"][\"src_id\"] == 3 and st[\"B4_TH\"][\"abort_0x24_active_lease\"][\"err_hex\"] == \"0x04\" and st[\"immediate_th_to_mc_transition\"][\"elapsed_since_th_sec\"] < 1.0 and st[\"post_upgrade_recovery\"][\"spurious_nack_count\"] == 0; print(\"[PASS] Docker QA verified SLICE-05 provenance, receipt & 0x21 payload hashes\")'"}

acceptance_criteria:
  - "真机硬件与防伪溯源：C308L (root@192.168.1.101:/dev/ttyS1 @ 921600 8N1 raw termios) 全程禁用 probe-rs/SWD (probe_rs_used=false) 且 Option A 加热 0%；ttyS1_hw_provenance.log 实证 /sys/class/tty/ttyS1/device 物理绑定及 UART 中断计数差值 (>100)，hil_raw_hex.log 重组 151 块 TH 与 751 块 MC 0x21 载荷与 0x7B623D9A 固件 SHA256/CRC32 一致"
  - "HIL-FINDING-01 消缺验证 (B4_TH)：MC 与 TH 运行 mcu-p3@7b623d9a (0x7B623D9A)（见 INTEGRATOR_hil_report.md §2.1 初始 0xB865222C->0x7B623D9A 灰度升级及归档单次全闭环 B0_MC_ROLLOUT 751 块重刷记录），在 L3 5000ms 活跃租约期内发 DST=0x03 CMD=0x24 必须收到 SRC=0x03 NACK 0x04（零 SRC=0x02 NACK 0x05），4B 0x23 回 SRC=0x03 NACK 0x06，0x01/0x03/0x14 双向透传与 DST=0x02 0x01/0x03/0x14 查询零阻塞、0x10 本地级联让路回 NACK 0x05、0x1D(1) 驻留 TH Boot 刷新 boot_id"
  - "无等待跨板衔接与全量升级 (B2_TH -> <1.0s -> B2_MC)：B2_TH (151 块) 升至 TH 0x7B623D9A 并刷新 boot_id 后不等待 5s 租约，在 <1.0s 内直发 DST=0x02 0x1D(2) 立即收到 SRC=0x02 CMD_ACK 并在 <2.0s 进 MC Boot；随后 B3_MC/B4_MC/B2_MC (751 块) 将 MC 刷至 0x7B623D9A 并刷新 boot_id（按用户已批准豁免政策将 MC Boot boot_id=0xC1E6CD05 复现记为 HIL-FINDING-02 非阻断已接受技术债，未实测的硬件寄存器行为诚实标为 [UNVERIFIED]）"
  - "租约释放与平面 B 恢复：静默 >=5.2s 等待 L3 租约释放后发送 DST=0x02 CMD=0x10 (0, 0) 安全级联（0% PWM）收到 SRC=0x02 CMD_ACK/0x15 TEMP_REPORT，350ms 监听无 USART2 幽灵 NACK 0x03"
  - "审批与非阻断诚实边界 (DEC-REM-1=A)：按 v1.5 已批准 DEC-REM-1=A 条件准出范围，物理 FAT32 U 盘插拔 (B5) 与外接独立 Debug UART 诚实标为 [UNVERIFIED / PENDING] 且非阻塞，结合 fast_gate (<3s) 与独立 Codex 双轴 APPROVED 升级 ledger.md 至 HIL-Verified"
