integration_cmd: >-
  python3 -c 'import subprocess; repos=["mcu-p3","printer-soc","test_harness","boot/bootloadermc","boot/bootloaderth","agents"]; dirty=[r for r in repos if subprocess.check_output(["git","-C",r,"status","--porcelain"],text=True).strip()]; assert not dirty, dirty; print("[PASS] 6 non-control repos strictly clean (0 diffs)")' &&
  python3 -c 'import subprocess, time; t0=time.monotonic(); r=subprocess.run(["python3", "project-control/tools/gates/fast_gate.py", "--workspace", ".", "--slice", "project-control/slices/SLICE-05.yaml"], capture_output=True, text=True); dt=time.monotonic()-t0; print((r.stdout + r.stderr).strip()); print(f"[PASS] fast_gate rc={r.returncode} elapsed_sec={dt:.3f} (<3.000s)"); assert r.returncode == 0 and dt < 3.0' &&
  python3 -c 'import hashlib, json, pathlib, re, struct, zlib;
  p = pathlib.Path("project-control/docs/evidence/SLICE-05");
  req = ["ttyS1_hw_provenance.log", "hil_raw_hex.log", "hil_deployment_receipt.json", "INTEGRATOR_hil_report.md"];
  assert all((p / f).is_file() and (p / f).stat().st_size > 0 for f in req);
  rec = json.loads((p / "hil_deployment_receipt.json").read_text(encoding="utf-8"));
  assert rec.get("passed") is True and rec.get("port") == "/dev/ttyS1" and rec.get("baud") == 921600;
  assert rec.get("probe_rs_used") is False and rec.get("heating_pwm_pct") == 0;
  prov = rec.get("hw_provenance", {});
  assert prov.get("irq_after", 0) - prov.get("irq_before", 0) > 100 and "/dev/ttyS1" in prov.get("tty_device", "") and "pty" not in prov.get("tty_sysfs_device", "").lower();
  raw_bytes = (p / "hil_raw_hex.log").read_bytes();
  assert hashlib.sha256(raw_bytes).hexdigest() == rec["raw_hex_log"]["sha256"];
  raw = raw_bytes.decode("utf-8");
  st = rec["stages"];
  assert all(st[k].get("passed") is True for k in ("B1", "B0_MC_ROLLOUT", "B3_TH", "B4_TH", "B2_TH", "immediate_th_to_mc_transition", "B3_MC", "B4_MC", "B2_MC", "post_upgrade_recovery"));
  assert st["immediate_th_to_mc_transition"]["elapsed_since_th_sec"] < 1.0 and st["immediate_th_to_mc_transition"]["boot_entry_elapsed_sec"] < 2.0;
  assert st["B4_TH"]["abort_0x24_active_lease"]["src_id"] == 3 and st["B4_TH"]["abort_0x24_active_lease"]["err_hex"] == "0x04";
  assert st["post_upgrade_recovery"]["quiet_wait_sec"] >= 5.2 and st["post_upgrade_recovery"]["spurious_nack_count"] == 0;
  tx_th = [bytes.fromhex(m.group(1)) for m in re.finditer(r"\[B2_TH\][^\n]*\bTX\s+([0-9a-fA-F]+)", raw)];
  tx_mc = [bytes.fromhex(m.group(1)) for m in re.finditer(r"\[B2_MC\][^\n]*\bTX\s+([0-9a-fA-F]+)", raw)];
  d_th = {struct.unpack("<I", b[12:16])[0]: b[20:20 + struct.unpack("<H", b[16:18])[0]] for b in tx_th if len(b) >= 22 and b[0] == 0x55 and b[1] == 0xAA and b[5] == 0x21};
  d_mc = {struct.unpack("<I", b[12:16])[0]: b[20:20 + struct.unpack("<H", b[16:18])[0]] for b in tx_mc if len(b) >= 22 and b[0] == 0x55 and b[1] == 0xAA and b[5] == 0x21};
  th_pay = b"".join(d_th[k] for k in sorted(d_th));
  mc_pay = b"".join(d_mc[k] for k in sorted(d_mc));
  assert len(d_th) == 151 and len(th_pay) == 76864 and (zlib.crc32(th_pay) & 0xFFFFFFFF) == 0x6E82DD49;
  assert len(d_mc) == 751 and len(mc_pay) == 384112 and (zlib.crc32(mc_pay) & 0xFFFFFFFF) == 0x8DC0DC33;
  assert hashlib.sha256(th_pay).hexdigest() == rec["packages"]["th"]["payload_sha256"] and th_pay.count(bytes.fromhex("9a3d627b")) >= 1;
  assert hashlib.sha256(mc_pay).hexdigest() == rec["packages"]["mc"]["payload_sha256"] and mc_pay.count(bytes.fromhex("9a3d627b")) >= 1;
  rep = (p / "INTEGRATOR_hil_report.md").read_text(encoding="utf-8");
  assert "DEC-REM-1" in rep and "HIL-FINDING-02" in rep and "[UNVERIFIED / PENDING]" in rep;
  print("[PASS] SLICE-05 HIL receipt, IRQ provenance delta & wire-chunk SHA256/CRC32/0x7B623D9A verified")'

